children.source:
this.showBar && (
          <div
            class={{
              'md-search__bar': true,
              'md-search__bar--focused': this.focused,
              'md-search__bar--focus-ring': this.showFocusRing,
            }}
            part="bar"
            onClick={this.handleBarClick}
          >
            {!this.disabled && (
              <md-ripple ref={(el) => (this.rippleEl = el as HTMLElement)}></md-ripple>
            )}
            <span class="md-search__state-layer" part="state-layer" aria-hidden="true"></span>

            {this.renderLeading()}

            <input
              ref={(el) => (this.input = el)}
              class="md-search__input"
              part="input"
              type="search"
              role="combobox"
              value={this.value}
              placeholder={this.placeholder}
              disabled={this.disabled}
              aria-label={this.effectiveLabel()}
              aria-expanded={this.open ? 'true' : 'false'}
              aria-controls="md-search-panel"
              aria-autocomplete="list"
              autocomplete="off"
              spellcheck={false}
              onInput={this.handleInput}
              onFocus={this.handleInputFocus}
              onBlur={this.handleInputBlur}
              onKeyDown={this.handleInputKeyDown}
            />

            {this.renderTrailing()}
          </div>
        )

declarations.value:
var(--_container-elevation),
    0 0 0 var(--_focus-indicator-offset) var(--_container-color),
    0 0 0
      calc(var(--_focus-indicator-offset) + var(--_focus-indicator-thickness))
      var(--_focus-indicator-color)

opacity var(--md-sys-motion-duration-medium1, 250ms)
      var(--md-sys-motion-easing-emphasized, cubic-bezier(0.2, 0, 0, 1)),
    transform var(--md-sys-motion-duration-medium1, 250ms)
      var(--md-sys-motion-easing-emphasized, cubic-bezier(0.2, 0, 0, 1))
